    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="mx-auto max-w-text min-w-0">
          <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">
            {title}
          </h2>

          {/* Талон: сетка «листок из регистратуры» с линией отрыва */}
          <div className="mt-8 rounded-md border border-foreground bg-card text-card-foreground">
            <div className="grid grid-cols-1 divide-y divide-border sm:grid-cols-2 sm:divide-x sm:divide-y-0">
              <div className="px-6 py-6 sm:px-8">
                <p className="text-small font-semibold tracking-wide uppercase text-muted-foreground">
                  {service}
                </p>
              </div>
              <div className="px-6 py-6 sm:px-8">
                <p className="text-small font-semibold tracking-wide uppercase text-muted-foreground">
                  {doctor}
                </p>
              </div>
            </div>

            {/* Линия отрыва: штриховой край «бумажного» талона */}
            <div className="border-t border-dashed border-border" aria-hidden="true" />

            <div className="grid grid-cols-1 divide-y divide-border sm:grid-cols-2 sm:divide-x sm:divide-y-0">
              <div className="px-6 py-6 sm:px-8">
                <p className="text-small font-semibold tracking-wide uppercase text-muted-foreground">
                  {date}
                </p>
              </div>
              <div className="px-6 py-6 sm:px-8">
                <p className="text-small font-semibold tracking-wide uppercase text-muted-foreground">
                  {time}
                </p>
              </div>
            </div>
          </div>

          {note ? (
            <p className="mt-6 text-small text-muted-foreground wrap-break-word">{note}</p>
          ) : null}

          <div className="mt-8">
            <a
              href={action.href}
              className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-opacity duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            >
              {action.label}
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}

